//! Signal evaluation — and the machinery that makes a flattering answer hard to produce.
//!
//! `series` guards the DATA. This guards the CONCLUSION, and it exists because the dominant failure
//! in signal research is not a bad idea, it is an honest-looking measurement of a bad idea. Four
//! things produce a backtest that cannot be traded, and only the first is widely known:
//!
//! 1. **Look-ahead** — handled structurally: a signal is only ever handed
//!    [`series::bars_available_at`], so it cannot see the bar it is deciding on.
//! 2. **Costs** — a 2% edge traded fifty times a year against a 0.5% round trip is a LOSING
//!    strategy that backtests beautifully. So [`Costs`] is a required argument, exactly as
//!    `discretionary` is in `runway`, and the report shows gross and net side by side so the drag
//!    is visible rather than absorbed.
//! 3. **The benchmark** — a signal returning 8% on an instrument that returned 30% is a bad signal
//!    that looks good alone. Buy-and-hold on the SAME bars is computed every time and the verdict
//!    is relative to it.
//! 4. **Multiple testing** — this is the one that quietly ruins everything. Test two hundred signals
//!    against the same ten years and the best will look excellent BY ARITHMETIC, not by skill. The
//!    number of trials is an input, and the bar a result must clear rises with it.
//!
//! **The harness must be able to say no.** A verdict that is always a number is the same failure as
//! a backtest that always looks good, so short histories, thin trade counts and results inside the
//! noise are REFUSALS rather than small numbers.
use crate::series::{bars_available_at, Bar, VerifiedSeries};

/// What trading costs, as a fraction of the notional actually traded.
///
/// Applied to the CHANGE in position, so holding is free and flipping long-to-short pays twice. That
/// is what makes turnover expensive in the report rather than merely mentioned in a comment.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Costs {
    /// One-way cost: commission plus half the spread plus expected slippage. 0.001 is 10bps.
    pub per_turn: f64,
}

impl Costs {
    /// A deliberately UNFLATTERING default for a retail account on liquid daily bars.
    ///
    /// Not a promise about your broker — a starting point that errs toward pessimism, because a
    /// backtest that assumes free trading is the most common way to be wrong on paper and poor in
    /// practice.
    pub fn retail_daily() -> Costs {
        Costs { per_turn: 0.001 }
    }

    pub fn free() -> Costs {
        Costs { per_turn: 0.0 }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct EvalOptions {
    /// REQUIRED. There is no default, for the same reason `runway` has none for discretionary
    /// spending: a zero assumed silently is the flattering kind of wrong.
    pub costs: Costs,
    /// The fraction of the history used to FIND the result. The remainder judges it.
    pub in_sample_fraction: f64,
    /// Below this the history is too short to say anything, and the verdict is a refusal.
    pub min_bars: usize,
    /// Below this there are too few decisions for the result to be about the signal rather than
    /// about two lucky months.
    pub min_trades: usize,
    /// HOW MANY SIGNALS WERE TESTED against this data, including this one.
    ///
    /// The bar a result must clear rises with it, because the best of N random signals looks good
    /// by arithmetic. Passing 1 while having tried forty is how a backtest lies to its author.
    pub trials: usize,
    /// Bars in a year. 252 for daily equities.
    pub periods_per_year: f64,
}

impl Default for EvalOptions {
    fn default() -> Self {
        EvalOptions { costs: Costs::retail_daily(), in_sample_fraction: 0.7, min_bars: 250, min_trades: 20, trials: 1, periods_per_year: 252.0 }
    }
}

/// What a signal wants to hold, given only what it could have known.
///
/// `-1.0` fully short, `0.0` flat, `1.0` fully long. Fractions are allowed and are how a
/// conviction-weighted or risk-scaled signal expresses itself.
pub trait Signal {
    fn name(&self) -> &str;

    /// The position to hold over the NEXT bar.
    ///
    /// `history` is every bar STRICTLY BEFORE the one being decided, so reading the future is not
    /// something an implementer has to remember to avoid — it is not on offer.
    fn position(&self, history: &[Bar]) -> f64;
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Stats {
    pub periods: usize,
    /// Compounded return over the window, as a fraction.
    pub total_return: f64,
    /// Annualised, geometric.
    pub cagr: f64,
    /// Annualised mean over annualised standard deviation. NONE when nothing varied.
    pub sharpe: Option<f64>,
    /// Worst peak-to-trough fall in the equity curve, as a POSITIVE fraction.
    pub max_drawdown: f64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verdict {
    /// Beats buy-and-hold NET of costs, and holds up out of sample.
    Promising,
    /// Indistinguishable from luck once the number of signals tried is accounted for.
    InsideTheNoise,
    /// Real, and smaller than simply holding the thing.
    LosesToBuyAndHold,
    /// Gross of costs it works; net of them it does not.
    EatenByCosts,
    /// Not enough to say anything. The honest answer, and a common one.
    Refused,
}

impl Verdict {
    pub fn label(self) -> &'static str {
        match self {
            Verdict::Promising => "promising",
            Verdict::InsideTheNoise => "inside-the-noise",
            Verdict::LosesToBuyAndHold => "loses-to-buy-and-hold",
            Verdict::EatenByCosts => "eaten-by-costs",
            Verdict::Refused => "refused",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Evaluation {
    pub signal: String,
    pub symbol: String,
    pub verdict: Verdict,
    /// Why, in one sentence a person can act on.
    pub why: String,
    /// NET of costs, over the whole history.
    pub net: Option<Stats>,
    /// GROSS, so the cost drag is visible rather than absorbed into one number.
    pub gross: Option<Stats>,
    /// Buy-and-hold over exactly the same bars.
    pub benchmark: Option<Stats>,
    /// The half the result was found on, and the half that judges it.
    pub in_sample: Option<Stats>,
    pub out_of_sample: Option<Stats>,
    /// How much of the gross return the costs took, as a fraction of notional.
    pub cost_drag: f64,
    /// Position changes. A signal with four of them has not been measured, it has been anecdoted.
    pub trades: usize,
    /// Sum of |position change| — what the strategy actually asks you to trade.
    pub turnover: f64,
    /// The t-statistic of the mean net period return.
    pub t_stat: Option<f64>,
    /// The t a result must beat GIVEN how many signals were tried.
    pub t_required: f64,
    /// Everything this rests on.
    pub caveats: Vec<String>,
}

/// The bar a t-statistic must clear, given how many signals were tested.
///
/// The expected maximum of `n` draws from a standard normal grows like `sqrt(2 ln n)`. That is the
/// whole argument: with forty signals tried, a t of 2 is what the BEST one looks like when none of
/// them work. This is a screen and not a proof — it assumes independent trials and normal returns,
/// and market returns are neither — but it is enormously better than comparing against zero, which
/// is what a backtest with no trial count is doing.
pub fn t_required_for(trials: usize) -> f64 {
    let n = trials.max(1) as f64;
    // At one trial the conventional two-sided 5% bar; above it, whichever is larger.
    (2.0 * n.ln()).sqrt().max(1.96)
}

fn stats_of(returns: &[f64], periods_per_year: f64) -> Stats {
    let n = returns.len();
    if n == 0 {
        return Stats { periods: 0, total_return: 0.0, cagr: 0.0, sharpe: None, max_drawdown: 0.0 };
    }
    let mut equity = 1.0_f64;
    let mut peak = 1.0_f64;
    let mut max_dd = 0.0_f64;
    for r in returns {
        equity *= 1.0 + r;
        peak = peak.max(equity);
        if peak > 0.0 {
            max_dd = max_dd.max((peak - equity) / peak);
        }
    }
    let total_return = equity - 1.0;
    let years = n as f64 / periods_per_year;
    let cagr = if years > 0.0 && equity > 0.0 { equity.powf(1.0 / years) - 1.0 } else { 0.0 };

    let mean = returns.iter().sum::<f64>() / n as f64;
    let var = if n > 1 { returns.iter().map(|r| (r - mean).powi(2)).sum::<f64>() / (n as f64 - 1.0) } else { 0.0 };
    let sd = var.sqrt();
    // ZERO VARIANCE IS NOT AN INFINITE SHARPE. It means nothing moved, which is a fact about the
    // data rather than a perfect strategy.
    let sharpe = if sd > 0.0 { Some(mean / sd * periods_per_year.sqrt()) } else { None };

    Stats { periods: n, total_return, cagr, sharpe, max_drawdown: max_dd }
}

fn refuse(signal: &str, symbol: &str, why: String, caveats: Vec<String>, t_required: f64) -> Evaluation {
    Evaluation {
        signal: signal.to_string(),
        symbol: symbol.to_string(),
        verdict: Verdict::Refused,
        why,
        net: None,
        gross: None,
        benchmark: None,
        in_sample: None,
        out_of_sample: None,
        cost_drag: 0.0,
        trades: 0,
        turnover: 0.0,
        t_stat: None,
        t_required,
        caveats,
    }
}

/// Run one signal over one series and say what it is worth.
///
/// # Execution, stated because it decides the answer
///
/// The position for a bar is chosen from every bar STRICTLY BEFORE it, then executed at that bar's
/// OPEN and held to the next open. That is a decision made on last night's close and acted on this
/// morning, which is a thing a person can actually do. Deciding on a close and earning that same
/// close is the standard flattering mistake and it is not reachable from here.
pub fn evaluate(series: &VerifiedSeries, signal: &dyn Signal, opts: &EvalOptions) -> Evaluation {
    let t_required = t_required_for(opts.trials);
    let symbol = series.meta().symbol.clone();
    let mut caveats: Vec<String> = Vec::new();
    if series.unverified() {
        caveats.push(format!("the series was never checked: {}", series.caveat().unwrap_or("no reason given")));
    }
    if opts.costs.per_turn <= 0.0 {
        caveats.push("costs were given as ZERO — this measures a market nobody trades in, and the net figures below are gross ones wearing a different name".to_string());
    }
    if opts.trials <= 1 {
        caveats.push("one trial was declared, so the bar below is the conventional single-test one — if this is the best of several signals you tried, that bar is too low and the verdict is too generous".to_string());
    }

    let bars = series.bars();
    if bars.len() < opts.min_bars {
        return refuse(
            signal.name(),
            &symbol,
            format!("{} bar(s) of history against a {} minimum — too short to distinguish a signal from a run of luck", bars.len(), opts.min_bars),
            caveats,
            t_required,
        );
    }

    // One decision per bar that has both an entry and an exit price: positions are taken at open[i]
    // and closed at open[i+1], so the last bar has no return to earn.
    let mut gross: Vec<f64> = Vec::new();
    let mut net: Vec<f64> = Vec::new();
    let mut bench: Vec<f64> = Vec::new();
    let mut turnover = 0.0_f64;
    let mut trades = 0usize;
    let mut held = 0.0_f64;

    for i in 0..bars.len().saturating_sub(1) {
        let date = bars[i].date();
        // THE STRUCTURAL GUARD. The signal cannot see bars[i] — only what closed before it.
        let history = bars_available_at(series, date);
        let want = signal.position(history).clamp(-1.0, 1.0);

        let entry = bars[i].open.minor;
        let exit = bars[i + 1].open.minor;
        if entry <= 0 {
            continue;
        }
        let r = (exit - entry) as f64 / entry as f64;

        let change = (want - held).abs();
        if change > f64::EPSILON {
            trades += 1;
            turnover += change;
        }
        let cost = change * opts.costs.per_turn;
        gross.push(want * r);
        net.push(want * r - cost);
        bench.push(r);
        held = want;
    }

    if trades < opts.min_trades {
        return refuse(
            signal.name(),
            &symbol,
            format!("{trades} position change(s) against a {} minimum — too few decisions for this to be a measurement of the signal rather than of two lucky months", opts.min_trades),
            caveats,
            t_required,
        );
    }

    let net_stats = stats_of(&net, opts.periods_per_year);
    let gross_stats = stats_of(&gross, opts.periods_per_year);
    let bench_stats = stats_of(&bench, opts.periods_per_year);

    let split = ((net.len() as f64) * opts.in_sample_fraction).round() as usize;
    let in_sample = stats_of(&net[..split.min(net.len())], opts.periods_per_year);
    let out_of_sample = stats_of(&net[split.min(net.len())..], opts.periods_per_year);

    let n = net.len() as f64;
    let mean = net.iter().sum::<f64>() / n;
    let sd = (net.iter().map(|r| (r - mean).powi(2)).sum::<f64>() / (n - 1.0).max(1.0)).sqrt();
    let t_stat = if sd > 0.0 { Some(mean / (sd / n.sqrt())) } else { None };

    let cost_drag = gross_stats.total_return - net_stats.total_return;

    // THE LADDER, in the order that matters. Each rung answers a different question, and answering
    // them in the wrong order is how a result gets talked up: something inside the noise is not
    // "slightly worse than buy-and-hold", it is nothing at all.
    let (verdict, why) = if t_stat.is_none_or(|t| t.abs() <= t_required) {
        // Two true things, and saying only the first leaves the more actionable one unsaid: the
        // t-test says the returns cannot be told from zero, and the comparison says whether it also
        // did worse than doing nothing. A reader deserves both.
        let also = if net_stats.total_return <= bench_stats.total_return {
            format!(" — and it returned {:.1}% against {:.1}% for simply holding, so it is not a near miss", net_stats.total_return * 100.0, bench_stats.total_return * 100.0)
        } else {
            String::new()
        };
        (
            Verdict::InsideTheNoise,
            format!(
                "t = {:.2} against a bar of {t_required:.2} for {} trial(s) — this is what the best of that many random signals looks like, so there is nothing here to act on{also}",
                t_stat.unwrap_or(0.0),
                opts.trials
            ),
        )
    } else if gross_stats.total_return > bench_stats.total_return && net_stats.total_return <= bench_stats.total_return {
        (
            Verdict::EatenByCosts,
            format!(
                "gross it beats holding by {:.1}%, net it does not — {:.1}% of return went to costs across {:.1} turns of the book",
                (gross_stats.total_return - bench_stats.total_return) * 100.0,
                cost_drag * 100.0,
                turnover
            ),
        )
    } else if net_stats.total_return <= bench_stats.total_return {
        (
            Verdict::LosesToBuyAndHold,
            format!(
                "net {:.1}% against {:.1}% for simply holding it — the signal is real and it is not worth the work",
                net_stats.total_return * 100.0,
                bench_stats.total_return * 100.0
            ),
        )
    } else if out_of_sample.total_return <= 0.0 {
        (
            Verdict::InsideTheNoise,
            format!(
                "it beats holding in sample and returns {:.1}% out of sample — a result that does not survive the half it was not fitted on is a description of the past",
                out_of_sample.total_return * 100.0
            ),
        )
    } else {
        (
            Verdict::Promising,
            format!(
                "net {:.1}% against {:.1}% for holding, and {:.1}% out of sample — worth more data, NOT worth money yet",
                net_stats.total_return * 100.0,
                bench_stats.total_return * 100.0,
                out_of_sample.total_return * 100.0
            ),
        )
    };

    Evaluation {
        signal: signal.name().to_string(),
        symbol,
        verdict,
        why,
        net: Some(net_stats),
        gross: Some(gross_stats),
        benchmark: Some(bench_stats),
        in_sample: Some(in_sample),
        out_of_sample: Some(out_of_sample),
        cost_drag,
        trades,
        turnover,
        t_stat,
        t_required,
        caveats,
    }
}

/// Run several signals over one series, with the trial count set to how many were actually run.
///
/// This is the ONLY honest way to test a batch: the bar rises with the number of attempts, so a
/// sweep cannot quietly grade itself against a single-test threshold. Best first, refusals last.
pub fn evaluate_all(series: &VerifiedSeries, signals: &[&dyn Signal], opts: &EvalOptions) -> Vec<Evaluation> {
    let with_trials = EvalOptions { trials: signals.len().max(opts.trials), ..*opts };
    let mut out: Vec<Evaluation> = signals.iter().map(|s| evaluate(series, *s, &with_trials)).collect();
    out.sort_by(|a, b| {
        let rank = |v: Verdict| match v {
            Verdict::Promising => 0,
            Verdict::EatenByCosts => 1,
            Verdict::LosesToBuyAndHold => 2,
            Verdict::InsideTheNoise => 3,
            Verdict::Refused => 4,
        };
        rank(a.verdict).cmp(&rank(b.verdict)).then_with(|| {
            b.net.map(|s| s.total_return).unwrap_or(f64::MIN).partial_cmp(&a.net.map(|s| s.total_return).unwrap_or(f64::MIN)).unwrap_or(std::cmp::Ordering::Equal)
        })
    });
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;
    use crate::series::{check_series, unverified_series, BarDate, CheckOptions, SeriesMeta};

    // SYNTHETIC FIXTURES ONLY — every price here is generated, none is market data.
    /// A real weekday calendar, walked with the same date arithmetic the rest of the crate uses.
    ///
    /// My first attempt computed the month arithmetically and overflowed past ~150 bars into dates
    /// like `2026-06-554`, which `BarDate` then truncated — so the series stopped being sorted and
    /// `bars_available_at`'s binary search returned nonsense. Three tests failed and NONE of them
    /// was the harness's fault. Generating dates properly is cheaper than debugging that twice.
    fn weekdays(n: usize) -> Vec<String> {
        let mut out = Vec::with_capacity(n);
        let mut d = "2026-01-05".to_string(); // a Monday
        while out.len() < n {
            if !crate::series::is_weekend(&d) {
                out.push(d.clone());
            }
            d = crate::obligations::add_days(&d, 1);
        }
        out
    }

    fn bar_on(date: &str, open: i64, close: i64) -> Bar {
        Bar {
            date_i: BarDate::new(date),
            open: usd(open),
            high: usd(open.max(close) + 1),
            low: usd(open.min(close) - 1),
            close: usd(close),
            volume: None,
        }
    }

    /// A deterministic pseudo-random walk. No `rand` dependency, and the same series every run.
    fn walk(n: usize, drift: f64) -> Vec<Bar> {
        let dates = weekdays(n);
        let mut px = 10_000.0_f64;
        let mut seed = 12_345u64;
        let mut out = Vec::new();
        for date in dates.iter().take(n) {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
            // `seed >> 33` is 31 bits, so dividing by 2^31 gives 0..1 — and subtracting one gave
            // -1..0, a "random walk" that only ever fell. Every signal that needs an up bar then
            // did nothing, and the tests were green over a fixture that tested nothing.
            let u = ((seed >> 33) as f64 / (1u64 << 31) as f64) * 2.0 - 1.0; // -1..1
            let open = px;
            px *= 1.0 + drift + u * 0.02;
            out.push(bar_on(date, open.round() as i64, px.round() as i64));
        }
        out
    }

    fn series_of(bars: &[Bar]) -> VerifiedSeries {
        unverified_series(bars, SeriesMeta::new("SYNTH", "generated"), "a synthetic fixture, not market data").expect("a caveat")
    }

    struct AlwaysLong;
    impl Signal for AlwaysLong {
        fn name(&self) -> &str {
            "always-long"
        }
        fn position(&self, _h: &[Bar]) -> f64 {
            1.0
        }
    }

    /// Flips every bar — the pure turnover machine, for measuring what costs do.
    struct Alternating;
    impl Signal for Alternating {
        fn name(&self) -> &str {
            "alternating"
        }
        fn position(&self, h: &[Bar]) -> f64 {
            if h.len().is_multiple_of(2) { 1.0 } else { -1.0 }
        }
    }

    /// The one that cheats — it is handed only history, so it CANNOT.
    struct LastBarUp;
    impl Signal for LastBarUp {
        fn name(&self) -> &str {
            "last-bar-up"
        }
        fn position(&self, h: &[Bar]) -> f64 {
            match h.last() {
                Some(b) if b.close.minor > b.open.minor => 1.0,
                _ => 0.0,
            }
        }
    }

    #[test]
    fn the_fixture_walk_actually_walks_in_both_directions() {
        // It did not, once: the PRNG produced only negative draws and the series fell every single
        // bar. Every test needing an up bar then exercised nothing while staying green, which is
        // this repo's signature failure reproduced inside its own fixtures.
        let bars = walk(300, 0.0);
        let up = bars.iter().filter(|b| b.close.minor > b.open.minor).count();
        let down = bars.iter().filter(|b| b.close.minor < b.open.minor).count();
        assert!(up > 100, "only {up} up bars in 300");
        assert!(down > 100, "only {down} down bars in 300");
        // And the dates are sorted and real, because an unsorted series breaks the binary search
        // inside `bars_available_at` without saying so.
        assert!(bars.windows(2).all(|w| w[0].date() < w[1].date()));
        assert!(bars.iter().all(|b| !crate::series::is_weekend(b.date())));
    }

    #[test]
    fn a_signal_is_handed_only_what_closed_before_the_bar_it_decides() {
        // THE STRUCTURAL GUARD, asserted rather than trusted. The signal records the last date it
        // was shown; it must always be strictly before the bar being traded.
        use std::cell::RefCell;
        struct Spy(RefCell<Vec<String>>);
        impl Signal for Spy {
            fn name(&self) -> &str {
                "spy"
            }
            fn position(&self, h: &[Bar]) -> f64 {
                self.0.borrow_mut().push(h.last().map(|b| b.date().to_string()).unwrap_or_default());
                1.0
            }
        }
        let bars = walk(300, 0.0);
        let s = series_of(&bars);
        let spy = Spy(RefCell::new(Vec::new()));
        let _ = evaluate(&s, &spy, &EvalOptions { min_trades: 0, ..EvalOptions::default() });
        let seen = spy.0.borrow();
        for (i, last_seen) in seen.iter().enumerate() {
            assert!(last_seen.as_str() < bars[i].date(), "bar {i}: signal saw {last_seen}, deciding on {}", bars[i].date());
        }
        assert_eq!(seen[0], "", "the first decision has NO history at all, not one bar of it");
    }

    #[test]
    fn costs_are_charged_on_the_change_in_position_so_holding_is_free() {
        let bars = walk(300, 0.0005);
        let s = series_of(&bars);
        // Always-long changes position ONCE, at the start.
        let hold = evaluate(&s, &AlwaysLong, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert_eq!(hold.trades, 1);
        assert!((hold.turnover - 1.0).abs() < 1e-9);
        assert!(hold.cost_drag < 0.002, "one turn at 10bps is a rounding error over 300 bars");

        // Alternating flips every bar: ~2.0 of turnover per bar, and the costs eat it alive.
        let flip = evaluate(&s, &Alternating, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert!(flip.turnover > 500.0, "turnover was {}", flip.turnover);
        assert!(flip.cost_drag > hold.cost_drag * 100.0, "the same 10bps costs a hundred times more when you trade a hundred times more");
    }

    #[test]
    fn zero_costs_are_allowed_and_said_out_loud() {
        let bars = walk(300, 0.0);
        let s = series_of(&bars);
        let e = evaluate(&s, &Alternating, &EvalOptions { costs: Costs::free(), min_trades: 1, ..EvalOptions::default() });
        assert_eq!(e.cost_drag, 0.0);
        assert!(e.caveats.iter().any(|c| c.contains("measures a market nobody trades in")));
    }

    #[test]
    fn the_harness_can_say_yes_or_it_is_not_measuring_anything() {
        // A machine that always refuses is not conservative, it is broken — and it would be
        // indistinguishable from a correct one on every test above, all of which expect a no.
        // So: a series with REAL exploitable structure, and a signal that exploits it.
        //
        // The structure is genuine autocorrelation — the next bar continues the last one — which
        // does not exist in markets and is entirely the point. If a signal reading it cannot be
        // rated promising, nothing ever will be.
        let dates = weekdays(900);
        let mut bars = Vec::new();
        let mut px = 10_000.0_f64;
        let mut up = true;
        let mut seed = 4_242u64;
        for (i, d) in dates.iter().enumerate() {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
            // Flip direction only occasionally, so runs persist and the last bar predicts the next.
            if (seed >> 40).is_multiple_of(8) {
                up = !up;
            }
            let open = px;
            px *= if up { 1.004 } else { 0.996 };
            let _ = i;
            bars.push(bar_on(d, open.round() as i64, px.round() as i64));
        }
        let s = series_of(&bars);
        let e = evaluate(&s, &LastBarUp, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert_eq!(e.verdict, Verdict::Promising, "why: {}", e.why);
        assert!(e.net.unwrap().total_return > e.benchmark.unwrap().total_return);
        assert!(e.out_of_sample.unwrap().total_return > 0.0, "and it survives the half it was not fitted on");
        assert!(e.t_stat.unwrap().abs() > e.t_required);
        // Even then it says what it is: worth more data, NOT worth money.
        assert!(e.why.contains("worth more data, NOT worth money yet"));
    }

    #[test]
    fn a_short_history_is_refused_rather_than_answered_quietly() {
        let bars = walk(40, 0.001);
        let e = evaluate(&series_of(&bars), &AlwaysLong, &EvalOptions::default());
        assert_eq!(e.verdict, Verdict::Refused);
        assert!(e.why.contains("too short to distinguish a signal from a run of luck"));
        // A refusal carries NO numbers. Reporting a Sharpe over forty bars is the thing this exists
        // to prevent.
        assert!(e.net.is_none() && e.gross.is_none() && e.benchmark.is_none() && e.t_stat.is_none());
    }

    #[test]
    fn too_few_decisions_is_refused_because_it_measures_two_lucky_months() {
        let bars = walk(300, 0.001);
        // Always-long makes exactly one position change over the whole history.
        let e = evaluate(&series_of(&bars), &AlwaysLong, &EvalOptions::default());
        assert_eq!(e.verdict, Verdict::Refused);
        assert!(e.why.contains("1 position change(s) against a 20 minimum"));
    }

    #[test]
    fn the_bar_rises_with_the_number_of_signals_tried() {
        // The expected maximum of n standard normals grows like sqrt(2 ln n). With forty signals
        // tried, a t of 2 is what the BEST one looks like when none of them work.
        assert!((t_required_for(1) - 1.96).abs() < 1e-9, "one trial is the conventional bar");
        assert!((t_required_for(2) - 1.96).abs() < 1e-9, "and it does not fall below it");
        assert!(t_required_for(40) > 2.6, "got {}", t_required_for(40));
        assert!(t_required_for(200) > 3.2, "got {}", t_required_for(200));
        assert!(t_required_for(1_000) > t_required_for(200));
        assert!((t_required_for(0) - 1.96).abs() < 1e-9, "zero trials cannot lower the bar");
    }

    #[test]
    fn a_sweep_grades_itself_against_the_number_of_signals_it_actually_ran() {
        let bars = walk(400, 0.0);
        let s = series_of(&bars);
        let sigs: Vec<&dyn Signal> = vec![&AlwaysLong, &Alternating, &LastBarUp];
        let out = evaluate_all(&s, &sigs, &EvalOptions { min_trades: 1, trials: 1, ..EvalOptions::default() });
        assert_eq!(out.len(), 3);
        // THE POINT: the caller said one trial, three were run, and the bar used is the one for
        // three. A sweep cannot quietly grade itself against a single-test threshold.
        assert!(out.iter().all(|e| (e.t_required - t_required_for(3)).abs() < 1e-9));
        // Refusals sort last, so the top of the list is never a thing that was not measured.
        let ranks: Vec<&str> = out.iter().map(|e| e.verdict.label()).collect();
        assert!(ranks.iter().position(|v| *v == "refused").unwrap_or(99) >= ranks.len() - 1 || !ranks.contains(&"refused"));
    }

    #[test]
    fn noise_is_called_noise_rather_than_a_small_edge() {
        // A driftless random walk contains nothing. Whatever a signal scores on it is luck, and the
        // verdict has to say so rather than reporting a modest-looking return.
        let bars = walk(500, 0.0);
        let e = evaluate(&series_of(&bars), &LastBarUp, &EvalOptions { min_trades: 1, trials: 20, ..EvalOptions::default() });
        assert_eq!(e.verdict, Verdict::InsideTheNoise, "why: {}", e.why);
        assert!(e.why.contains("what the best of that many random signals looks like"));
        // The numbers are still reported — refusing to show them would stop anyone checking.
        assert!(e.net.is_some() && e.benchmark.is_some());
    }

    #[test]
    fn a_signal_that_only_works_in_sample_does_not_survive_the_other_half() {
        let bars = walk(600, 0.0);
        let s = series_of(&bars);
        let e = evaluate(&s, &LastBarUp, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        // In or out of sample, both halves are computed and reported separately — a single
        // whole-history number cannot show the difference, which is the difference that matters.
        assert!(e.in_sample.is_some() && e.out_of_sample.is_some());
        let (i, o) = (e.in_sample.unwrap(), e.out_of_sample.unwrap());
        assert_eq!(i.periods + o.periods, e.net.unwrap().periods, "every period is in exactly one half");
        assert!(i.periods > o.periods, "70/30 by default");
    }

    #[test]
    fn zero_variance_is_not_an_infinite_sharpe() {
        let flat: Vec<Bar> = weekdays(300).iter().map(|d| bar_on(d, 10_000, 10_000)).collect();
        let e = evaluate(&series_of(&flat), &Alternating, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        // Nothing moved. That is a fact about the DATA, not a perfect strategy, and a Sharpe of
        // infinity is exactly the kind of number that would get acted on.
        assert!(e.benchmark.unwrap().sharpe.is_none());
        assert_eq!(e.benchmark.unwrap().total_return, 0.0);
    }

    #[test]
    fn an_unchecked_series_carries_its_caveat_into_the_result() {
        let bars = walk(300, 0.001);
        let e = evaluate(&series_of(&bars), &Alternating, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert!(e.caveats.iter().any(|c| c.contains("the series was never checked")));
        // And a CHECKED one does not.
        let checked = check_series(&bars, SeriesMeta::new("SYNTH", "generated"), &CheckOptions { holidays: &[], stale_run: 500, split_move: 10.0 }).series;
        if let Some(cs) = checked {
            let e2 = evaluate(&cs, &Alternating, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
            assert!(!e2.caveats.iter().any(|c| c.contains("never checked")));
        }
    }

    #[test]
    fn the_drawdown_is_the_worst_fall_from_a_peak_and_not_the_worst_period() {
        // Down 10%, up 5%, down 10% — the worst single period is 10%, the worst peak-to-trough is
        // the compounding of both, and a strategy is lived through the second one.
        let s = stats_of(&[-0.10, 0.05, -0.10], 252.0);
        // 0.9 → 0.945 → 0.8505 against a peak of 1.0. Computed rather than eyeballed: my first
        // guess at this number was 0.1855 and it was simply wrong.
        assert!((s.max_drawdown - 0.1495).abs() < 1e-9, "got {}", s.max_drawdown);
        assert!(s.total_return < 0.0);
        // An empty window has nothing to fall from.
        assert_eq!(stats_of(&[], 252.0).max_drawdown, 0.0);
    }
